class Dsu {
    readonly int[] parent;
    readonly byte[] rank;                              // an upper bound on the tree height
    public int Count;                                  // how many groups right now
    public Dsu(int n) {
        parent = new int[n]; rank = new byte[n]; Count = n;
        for (int i = 0; i < n; i++) parent[i] = i;
    }
    public int Find(int x) {
        int root = x;
        while (parent[root] != root) root = parent[root];
        while (parent[x] != root) {                    // compression: the whole path straight to the root
            int up = parent[x];
            parent[x] = root;
            x = up;
        }
        return root;
    }
    public bool Union(int a, int b) {
        int ra = Find(a), rb = Find(b);
        if (ra == rb) return false;                    // already together: the edge is redundant
        if (rank[ra] < rank[rb]) (ra, rb) = (rb, ra);  // lower tree under the higher one
        parent[rb] = ra;
        if (rank[ra] == rank[rb]) rank[ra]++;          // equal ranks: the height may have grown by 1
        Count--;
        return true;
    }
}

